/**
 * Observation summaries: plain sentences that restate published values.
 *
 * These are generated by fixed rules from the snapshots, never by an AI
 * model. Each sentence stays at the observation level: it says what a source
 * reported, where and when. None compares, explains, predicts or attributes.
 * If a source is unavailable, it produces no sentence (the page says so
 * elsewhere) rather than a sentence about nothing.
 */

import type { FireSummary } from "./sources/firms";
import { regionLabel } from "./sources/datagovsg";
import { formatLocalDateTime, LOCAL_ZONE_LABEL } from "./time";
import type { Observation, SourceSnapshot } from "./types";

export interface Summary {
  text: string;
  source: string;
}

const number = new Intl.NumberFormat("en-GB");

function at(iso: string | null): string {
  const local = iso ? formatLocalDateTime(iso) : null;
  return local ? `${local} (${LOCAL_ZONE_LABEL})` : "an unreadable time";
}

function usable(snapshot: Pick<SourceSnapshot, "outcome">): boolean {
  return snapshot.outcome === "ok" || snapshot.outcome === "partial";
}

function withValues(observations: readonly Observation[], metric: string): (Observation & { value: number })[] {
  return observations.filter(
    (o): o is Observation & { value: number } => o.metric === metric && o.value !== null,
  );
}

function placeName(observation: Observation): string {
  const location = observation.location;
  if (location.kind === "region") return regionLabel(location.id);
  if (location.kind === "station") return location.name;
  return "an unnamed location";
}

/** "62 µg/m³", "1 knot", "3.5 knots". */
function withUnit(value: number, unit: string): string {
  if (!unit) return number.format(value);
  const singular = unit === "knots" && value === 1 ? "knot" : unit;
  return `${number.format(value)} ${singular}`;
}

/** "ranged from 127 (North) to 207 (West)", or "was 150 at every one". */
function range(values: (Observation & { value: number })[], unit: string): string {
  const sorted = [...values].sort((a, b) => a.value - b.value);
  const low = sorted[0];
  const high = sorted[sorted.length - 1];
  if (low.value === high.value) return `was ${withUnit(low.value, unit)} at every one`;
  return `ranged from ${withUnit(low.value, unit)} (${placeName(low)}) to ${withUnit(high.value, unit)} (${placeName(high)})`;
}

export function psiSummary(snapshot: SourceSnapshot): Summary | null {
  if (!usable(snapshot)) return null;
  const values = withValues(snapshot.observations, "psi_24h");
  if (values.length === 0) return null;
  return {
    text: `For ${at(snapshot.latestObservedAt)}, across the ${values.length} Singapore regions reporting, NEA’s 24-hour PSI ${range(values, "")}.`,
    source: "NEA via data.gov.sg",
  };
}

export function pm25Summary(snapshot: SourceSnapshot): Summary | null {
  if (!usable(snapshot)) return null;
  const values = withValues(snapshot.observations, "pm25_1h");
  if (values.length === 0) return null;
  return {
    text: `For ${at(snapshot.latestObservedAt)}, across the ${values.length} Singapore regions reporting, NEA’s 1-hour PM2.5 concentration ${range(values, "µg/m³")}.`,
    source: "NEA via data.gov.sg",
  };
}

export function fireSummarySentence(
  snapshot: Pick<SourceSnapshot, "outcome">,
  summary: FireSummary | null,
): Summary | null {
  if (!usable(snapshot) || !summary) return null;
  if (summary.total === 0) {
    return {
      text: "NASA FIRMS reported no VIIRS detections inside the map window in the files retrieved. Zero detections is not zero fires.",
      source: "NASA FIRMS",
    };
  }
  return {
    text: `VIIRS instruments on NOAA satellites recorded ${number.format(summary.total)} thermal-anomaly detections inside the map window, acquired between ${at(summary.earliest)} and ${at(summary.latest)}. Detections are not fires, and say nothing about cause.`,
    source: "NASA FIRMS",
  };
}

export function windSpeedSummary(snapshot: SourceSnapshot): Summary | null {
  if (!usable(snapshot)) return null;
  const values = withValues(snapshot.observations, "wind_speed");
  if (values.length === 0) return null;
  return {
    text: `For ${at(snapshot.latestObservedAt)}, across the ${values.length} Singapore weather stations reporting, the 10-minute mean wind speed ${range(values, "knots")}.`,
    source: "MSS via data.gov.sg",
  };
}

export function rainfallSummary(snapshot: SourceSnapshot): Summary | null {
  if (!usable(snapshot)) return null;
  const values = withValues(snapshot.observations, "rainfall_5min");
  if (values.length === 0) return null;
  const raining = values.filter((o) => o.value > 0).length;
  return {
    text:
      raining === 0
        ? `In the five minutes to ${at(snapshot.latestObservedAt)}, none of the ${values.length} Singapore rain gauges that reported a value recorded rain.`
        : `In the five minutes to ${at(snapshot.latestObservedAt)}, ${raining} of the ${values.length} Singapore rain gauges that reported a value recorded rain.`,
    source: "MSS via data.gov.sg",
  };
}
